function plCover(ctx, img, W, H) { const w = img.naturalWidth || img.width, h = img.naturalHeight || img.height; const s = Math.max(W / w, H / h); ctx.drawImage(img, (W - w * s) / 2, (H - h * s) / 2, w * s, h * s); }
