  const [c1, c2, c3] = p.theme && p.theme.length === 3 ? p.theme : MP_THEMES[0];
  const g = ctx.createLinearGradient(0, 0, PW, PH); g.addColorStop(0, c1); g.addColorStop(.55, c2); g.addColorStop(1, c3); ctx.fillStyle = g; ctx.fillRect(0, 0, PW, PH);
  const glow = ctx.createRadialGradient(540, 520, 20, 540, 520, 620); glow.addColorStop(0, 'rgba(255,255,255,.38)'); glow.addColorStop(1, 'rgba(255,255,255,0)'); ctx.fillStyle = glow; ctx.fillRect(0, 0, PW, PH);
  ctx.strokeStyle = 'rgba(255,255,255,.14)'; ctx.lineWidth = 3; [240, 360, 480, 600].forEach(r => { ctx.beginPath(); ctx.arc(540, 520, r, 0, Math.PI * 2); ctx.stroke(); });
