  if (p.glyph) { ctx.font = `300px ${EMOJI}`; ctx.textBaseline = 'middle'; ctx.fillText(p.glyph, 540, 520); ctx.textBaseline = 'alphabetic'; }
  ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.35)'; ctx.shadowBlur = 24; ctx.shadowOffsetY = 6; ctx.fillStyle = '#fff'; plFit(ctx, p.title || '', 800, FONT_B, 900, 150, 60); ctx.fillText(p.title || '', 540, 860); ctx.restore();
  if (p.subtitle) { ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.font = `600 38px ${FONT_D}`; if ('letterSpacing' in ctx) ctx.letterSpacing = '6px'; ctx.fillText(p.subtitle, 540, 940); if ('letterSpacing' in ctx) ctx.letterSpacing = '0px'; }
