    <label class="dw-row" style="border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-top:12px"><span><b>${t('pf_publish')}</b><br><small class="r-meta">${t('pf_publish_n')}</small></span><input type="checkbox" ${p.active ? 'checked' : ''} onchange="saDraft.active=this.checked"></label>
    </div></div>
