/* bulk upload (ported from MahaPoster components/admin/bulk-upload.tsx) */
let BULK = null;
function openBulk() { BULK = { rows: [], category: (libOf().categories[0] || {}).id || 'festival', segments: [], active: true, noDate: false, defaultDate: today(), startDate: today(), perDay: 1, busy: false, skipped: 0, err: '' }; drawBulk(); }
function drawBulk() {
  const B = BULK, lib = libOf(), dates = new Set(B.rows.map(r => r.date)).size;
  openSheet(head(t('bu_title')) + `<div class="bu-tip"><b>${t('bu_tip')}</b><p class="r-meta" style="margin:4px 0 0">${t('bu_tip2', { n: MAX_FILES })}</p></div>
    <div class="fields"><div class="f"><label for="bu_c">${t('bu_cat')}</label><select id="bu_c" onchange="BULK.category=this.value">${lib.categories.map(c => `<option value="${c.id}" ${c.id === B.category ? 'selected' : ''}>${esc(c.names.en)} · ${esc(planOf(c.tier).name || c.tier)}</option>`).join('')}</select></div>
      <div class="f"><label for="bu_d">${t('bu_defdate')}</label><input id="bu_d" type="date" value="${B.defaultDate}" ${B.noDate ? 'disabled' : ''} onchange="BULK.defaultDate=this.value"></div></div>
    <label class="dw-row bu-sw"><span><b>${t('bu_nodate')}</b><br><small class="r-meta">${t('bu_nodate_n')}</small></span><input type="checkbox" ${B.noDate ? 'checked' : ''} onchange="BULK.noDate=this.checked;drawBulk()"></label>
    <b class="dw-h">${t('bu_brand')}</b>${segPicker(B.segments, 'bulkSeg()')}
    <label class="up-zone" style="margin-top:12px"><span style="font-size:26px">⇪</span><b>${B.busy ? t('bu_reading') : B.rows.length ? t('bu_more') : t('bu_choose')}</b><input type="file" accept="image/*" multiple hidden onchange="bulkPick(this)" ${B.busy ? 'disabled' : ''}></label>
    ${B.skipped ? `<p class="r-meta" style="color:var(--warn)">${t('bu_skipped', { n: B.skipped })}</p>` : ''}
    ${B.rows.length ? `<div class="bu-spread">${B.noDate ? '' : `<div class="f"><label for="bu_s">${t('bu_spread')}</label><input id="bu_s" type="date" value="${B.startDate}" onchange="BULK.startDate=this.value"></div>
        <div class="f"><label for="bu_n">${t('bu_perday')}</label><input id="bu_n" type="number" min="1" value="${B.perDay}" style="width:90px" onchange="BULK.perDay=Number(this.value)||1"></div><button class="btn" onclick="bulkSpread()">${t('bu_assign')}</button>`}
        <span class="r-meta" style="margin-left:auto">${t('bu_count', { n: B.rows.length })}${B.noDate ? ' · ' + t('always') : ' · ' + t('bu_dates', { n: dates })}</span></div>
      <ul class="bu-list">${B.rows.map(r => `<li><img src="${r.dataUrl}" alt=""><input class="search" value="${esc(r.title)}" aria-label="Title for ${esc(r.file)}" oninput="bulkUpd('${r.key}','title',this.value)">
        ${B.noDate ? `<span class="r-meta bu-always">${t('always')}</span>` : `<input class="search ${validDate(r.date) ? '' : 'bad'}" type="date" value="${r.date}" aria-label="Date for ${esc(r.file)}" onchange="bulkUpd('${r.key}','date',this.value)">`}
        <button class="btn small" aria-label="Remove ${esc(r.file)}" onclick="BULK.rows=BULK.rows.filter(x=>x.key!=='${r.key}');drawBulk()">×</button></li>`).join('')}</ul>` : ''}
    <label class="dw-row bu-sw"><span><b>${t('bu_publish')}</b><br><small class="r-meta">${t('bu_publish_n')}</small></span><input type="checkbox" ${B.active ? 'checked' : ''} onchange="BULK.active=this.checked"></label>
    ${B.err ? `<p role="alert" style="color:var(--danger)">${esc(B.err)}</p>` : ''}
    <div class="sheet-foot"><button class="btn" onclick="closeSheet()">${t('cancel')}</button><button class="btn primary" ${!B.rows.length || B.busy ? 'disabled' : ''} onclick="bulkSave()">${B.rows.length ? t('bu_save', { n: B.rows.length }) : t('pf_save')}</button></div>`);
}
function bulkSeg() { const v = [...document.querySelectorAll('.sheet .kchip input:checked')].map(x => x.value); if (v.length && !BULK.segments.length) BULK.noDate = true; BULK.segments = v; drawBulk(); }
function bulkUpd(key, k, v) { const r = BULK.rows.find(x => x.key === key); if (r) r[k] = v; }
async function bulkPick(inp) {
  const files = [...(inp.files || [])].slice(0, MAX_FILES); inp.value = ''; if (!files.length) return;
  BULK.busy = true; BULK.err = ''; drawBulk(); let bad = 0;
  // Sort by the date in the file name (both YYYY-MM-DD and DD-MM-YYYY), then by name – a plain name sort puts "31-12-2026" before "2026-12-25".
  const dateOf = f => { try { return parseFileName(f.name).date || ''; } catch { return ''; } };
  for (const f of files.sort((a, b) => dateOf(a).localeCompare(dateOf(b)) || a.name.localeCompare(b.name, undefined, { numeric: true }))) {
    try { const { date, title } = parseFileName(f.name); BULK.rows.push({ key: `${f.name}-${f.size}-${Math.random().toString(36).slice(2, 7)}`, file: f.name, dataUrl: await toPosterImage(f), title, date: date || BULK.defaultDate }); } catch (e) { bad++; }
  }
  BULK.skipped = bad; BULK.busy = false; drawBulk();
}
function bulkSpread() { if (!validDate(BULK.startDate)) return; const n = Math.max(1, BULK.perDay); BULK.rows.forEach((r, i) => { const d = new Date(BULK.startDate + 'T12:00:00'); d.setDate(d.getDate() + Math.floor(i / n)); r.date = d.toISOString().slice(0, 10); }); drawBulk(); }
async function bulkSave() {
  const B = BULK; if (!B.rows.length) { B.err = t('bu_need'); drawBulk(); return; }
  const noTitle = B.rows.filter(r => !r.title.trim()).length, badDate = B.noDate ? 0 : B.rows.filter(r => !validDate(r.date)).length;
  if (noTitle || badDate) { B.err = (noTitle ? t('bu_notitle', { n: noTitle }) : '') + (badDate ? t('bu_nodatev', { n: badDate }) : ''); drawBulk(); return; }
  B.busy = true; const lib = clone(libOf()); let n = Math.max(0, ...lib.posters.map(p => parseInt(String(p.id).replace(/\D/g, ''), 10) || 0)); let done = 0;
  for (const [i, r] of B.rows.entries()) {
    toast(t('bu_uploading', { a: i + 1, b: B.rows.length }));
    try { const j = await api('POST', '/api/sa/asset', { data: r.dataUrl }); lib.posters.push({ id: `p${++n}`, title: r.title.trim(), subtitle: '', eyebrow: '', category: B.category, date: B.noDate ? '' : r.date, glyph: '✨', theme: MP_THEMES[i % MP_THEMES.length], imageId: j.id, active: B.active, segments: B.segments }); done++; } catch (e) {}
  }
  B.busy = false; if (await saSaveLib(lib)) { closeSheet(); toast(t('bu_done', { n: done, x: B.active ? t('bu_live') : t('bu_hidden') })); }
}
/* categories & dealer types (ported from MahaPoster admin/categories + businesses) */
