function nameForm(c, withTier) { return `<div class="fields"><div class="f full"><label for="nf_en">${t('name_en')}</label><input id="nf_en" value="${esc(c.names.en)}"></div><div class="f"><label for="nf_hi">${t('name_hi')}</label><input id="nf_hi" value="${esc(c.names.hi)}"></div><div class="f"><label for="nf_mr">${t('name_mr')}</label><input id="nf_mr" value="${esc(c.names.mr)}"></div>
  ${withTier ? `<div class="f"><label for="nf_t">${t('pf_plan')}</label><select id="nf_t">${SA.plans.map(p => `<option value="${p.id}" ${c.tier === p.id ? 'selected' : ''}>${esc(p.name)}</option>`).join('')}</select></div>` : ''}<div class="f"><label for="nf_s">${t('c_order')}</label><input id="nf_s" type="number" value="${c.sort}"></div></div>`; }
