function saEditCat(id) { const lib = libOf(); const ex = id && lib.categories.find(c => c.id === id); const c = ex ? clone(ex) : { id: '', names: { en: '', hi: '', mr: '' }, tier: 'basic', active: true, sort: lib.categories.length + 1 };
  openSheet(head(ex ? t('edit') : t('add_cat')) + nameForm(c, true) + `<div class="sheet-foot"><button class="btn" onclick="closeSheet()">${t('cancel')}</button><button class="btn primary" onclick="saSaveCat('${c.id}')">${t('save_info')}</button></div>`); }
async function saSaveCat(id) { const names = readNames(); if (!names.en) { toast(t('cat_en_req')); return; } const lib = clone(libOf()); const c = { names, tier: $('#nf_t').value, sort: Number($('#nf_s').value) || 1 };
  if (id) lib.categories = lib.categories.map(x => (x.id === id ? { ...x, ...c } : x)); else lib.categories.push({ id: slugify(names.en) || `cat-${lib.categories.length + 1}`, active: true, ...c });
  if (await saSaveLib(lib)) { closeSheet(); toast(t('cat_saved')); } }
async function saDelCat(id) { const lib = clone(libOf()); const c = lib.categories.find(x => x.id === id); const n = lib.posters.filter(p => p.category === id).length; if (n) { alert(t('cat_has', { n: c.names.en, c: n })); return; } if (!confirm(t('cat_del_c', { n: c.names.en }))) return; lib.categories = lib.categories.filter(x => x.id !== id); await saSaveLib(lib); }
function saEditSeg(id) { const lib = libOf(); const ex = id && lib.segments.find(c => c.id === id); const c = ex ? clone(ex) : { id: '', names: { en: '', hi: '', mr: '' }, active: true, sort: lib.segments.length + 1 };
  openSheet(head(ex ? t('edit') : t('add_seg')) + nameForm(c, false) + `<div class="sheet-foot"><button class="btn" onclick="closeSheet()">${t('cancel')}</button><button class="btn primary" onclick="saSaveSeg('${c.id}')">${t('save_info')}</button></div>`); }
async function saSaveSeg(id) { const names = readNames(); if (!names.en) { toast(t('cat_en_req')); return; } const lib = clone(libOf()); const c = { names, sort: Number($('#nf_s').value) || 1 };
  if (id) lib.segments = lib.segments.map(x => (x.id === id ? { ...x, ...c } : x)); else lib.segments.push({ id: slugify(names.en) || `seg-${lib.segments.length + 1}`, active: true, ...c });
  if (await saSaveLib(lib)) { closeSheet(); toast(t('saved_ok')); } }
async function saDelSeg(id) { const lib = clone(libOf()); const c = lib.segments.find(x => x.id === id); if (!confirm(t('cat_del_c', { n: c.names.en }))) return; lib.segments = lib.segments.filter(x => x.id !== id); lib.posters.forEach(p => { p.segments = (p.segments || []).filter(s => s !== id); }); await saSaveLib(lib); }
function saPosterSet() {
  const on = !!(SA.posterCfg && SA.posterCfg.designerApprove);
  return `<div class="card" style="margin-top:14px"><label class="dw-row" style="border:0"><span><b>${t('set_da')}</b><br><small class="r-meta">${t('set_da_n')}</small></span><input type="checkbox" ${on ? 'checked' : ''} onchange="saSetDA(this.checked)"></label></div>`;
}
async function saSetDA(v) { try { await api('PUT', '/api/sa/postercfg', { designerApprove: v }); await loadSA(); render(); toast(t('saved_ok')); } catch (e) { toast(t('save_err')); } }
/* per-dealer patti block inside the dealer sheet (ported from MahaPoster admin/users) */
let saPrevSlot = 0;
function saPattiBlock(x) {
  const dp = (SA.dealerPoster || {})[x.id] || { pattiStatus: 'pending', pattiImages: [null, null, null] }; const imgs = dp.pattiImages || [null, null, null];
  const segs = libOf().segments, st = dp.pattiStatus || 'pending', labels = ['Classic', 'Premium', 'Simple'];
  const msg = t('dp_msg', { n: x.ownerName || x.name });
  return `<fieldset id="dpBox"><legend>${t('dp_title')}</legend>
    <div class="fields"><div class="f"><label for="dp_seg">${t('dp_seg')}</label><select id="dp_seg" onchange="saDP('${x.id}',{segment:this.value})"><option value="">${t('dp_none')}</option>${segs.map(s => `<option value="${s.id}" ${dp.segment === s.id ? 'selected' : ''}>${esc(s.names.en)}</option>`).join('')}</select></div>
    <div class="f"><label>${t('dp_status')}</label><div>${pill(st === 'approved' ? 'green' : st === 'rejected' ? 'red' : 'amber', t('st_' + st))}</div></div></div>
    <div class="patti-row" style="margin-top:10px">${[0, 1, 2].map(i => `<div class="pattic ${saPrevSlot === i ? 'on' : ''}" onclick="saPrevSlot=${i};saDealer('${x.id}')">${imgs[i] ? `<img src="${photoSrc(imgs[i])}" alt="${labels[i]} patti">` : '<div class="patti-empty">—</div>'}<span>${t('dp_slot', { n: i + 1 })} · ${labels[i]}</span>
      <span class="acts" style="justify-content:center" onclick="event.stopPropagation()"><label class="btn small">${t('dp_up')}<input type="file" accept="image/png,image/*" hidden onchange="saPattiUp('${x.id}',${i},this)"></label>${imgs[i] ? `<button class="btn small" onclick="saPattiDel('${x.id}',${i})">×</button>` : ''}</span></div>`).join('')}</div>
    <p class="r-meta" id="dpErr" style="color:var(--danger)"></p>
    <div class="acts" style="justify-content:flex-start">${st !== 'approved' ? `<button class="btn primary" onclick="saDP('${x.id}',{pattiStatus:'approved'})">${t('dp_approve')}</button>` : `<button class="btn" onclick="saDP('${x.id}',{pattiStatus:'pending'})">${t('dp_back')}</button>`}
      ${st !== 'rejected' ? `<button class="btn" onclick="saDP('${x.id}',{pattiStatus:'rejected'})">${t('dp_reject')}</button>` : ''}
      ${x.phone ? `<a class="btn" target="_blank" rel="noopener" href="https://wa.me/91${waNum(x.phone)}?text=${encodeURIComponent(msg)}">${t('dp_wa')}</a>` : ''}</div></fieldset>`;
}
async function saDP(tid, body) { try { await api('PUT', '/api/sa/dealerposter/' + tid, body); await loadSA(); saDealer(tid); toast(t('saved_ok')); } catch (e) { toast(t('save_err')); } }
async function saPattiUp(tid, i, inp) {
  const f = inp.files && inp.files[0]; inp.value = ''; if (!f) return; const errEl = $('#dpErr');
  try { const data = await toPattiPng(f); const j = await api('POST', '/api/sa/asset', { data }); const imgs = [...(((SA.dealerPoster || {})[tid] || {}).pattiImages || [null, null, null])]; imgs[i] = j.id; await api('PUT', '/api/sa/dealerposter/' + tid, { pattiImages: imgs }); await loadSA(); saPrevSlot = i; saDealer(tid); toast(t('dp_ok', { i: i + 1 })); }
  catch (e) { if (errEl) errEl.textContent = e.message === 'ratio' ? t('dp_ratio', { i: i + 1, w: e.w, h: e.h }) : t('upload_err'); }
}
async function saPattiDel(tid, i) { const imgs = [...(((SA.dealerPoster || {})[tid] || {}).pattiImages || [null, null, null])]; imgs[i] = null; await saDP(tid, { pattiImages: imgs }); }

/* starter posters (national days by fixed date; lunar festivals as drafts – set the date each year) */
const nextOn = mmdd => { const tt = today(); const y = +tt.slice(0, 4); let d = `${y}-${mmdd}`; if (d < tt) d = `${y + 1}-${mmdd}`; return d; };
