  if (demo) list.push(P('st-today', 'good-morning', today(), '☀️', 'teal', 'शुभ प्रभात', 'Good Morning', 'HAVE A GREAT DAY'), P('st-today2', 'offer', today(), '🚘', 'blue', 'आज का ऑफर', 'Today’s Car Mela', 'VISIT US TODAY'), P('st-tom', 'festival', plus(1), '🪔', 'saffron', 'शुभ पर्व', 'Shubh Parv', 'FESTIVE WISHES'), P('st-d3', 'jayanti', plus(3), '🌸', 'plum', 'जयंती विशेष', 'Jayanti', 'NAMAN'));
