async function saStarter() { const lib = clone(libOf()); const have = new Set(lib.posters.map(p => p.id)); const add = starterPosters(false).filter(p => !have.has(p.id)); lib.posters.push(...add); if (await saSaveLib(lib)) toast(t('starter_done', { n: add.length })); }

